import { BillingSettings } from "./billing-settings";

export function BillingPage() {
  return <BillingSettings />;
}

"use client";

import { CreditCardIcon, DownloadSimpleIcon } from "@phosphor-icons/react";
import { useState } from "react";
import { Alert } from "../../vip-ui/alert";
import { AnimatedNumber } from "../../vip-ui/animated-number";
import { Badge } from "../../vip-ui/badge";
import { Button } from "../../vip-ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "../../vip-ui/card";
import { Meter } from "../../vip-ui/meter";
import { Presence } from "../../vip-ui/presence";
import {
  RadioButton,
  RadioDescription,
  RadioField,
  RadioGroup,
  RadioIndicator,
  RadioLabel,
} from "../../vip-ui/radio-group";
import {
  Cell,
  Column,
  Row,
  Table,
  TableBody,
  TableContainer,
  TableHeader,
} from "../../vip-ui/table";
import { showToast } from "../../vip-ui/toast";
import { ConfirmPlanDialog } from "./confirm-plan-dialog";
import { type PaymentCard, PaymentMethodDialog } from "./payment-method-dialog";
import { SettingsShell } from "./settings-shell";

export const plans = [
  {
    id: "starter",
    name: "Starter",
    price: 0,
    seats: 5,
    description: "5 seats and 100,000 events each month",
  },
  {
    id: "pro",
    name: "Pro",
    price: 24,
    seats: 15,
    description: "15 seats and 2 million events each month",
  },
  {
    id: "business",
    name: "Business",
    price: 59,
    seats: 50,
    description: "50 seats, 10 million events each month, and SSO",
  },
];

export type Plan = (typeof plans)[number];

export const daysInPeriod = 30;
export const daysLeft = 28;

const seatsUsed = 12;

const usage = [
  { label: "Seats", value: seatsUsed, max: 15 },
  { label: "Events", value: 1_480_000, max: 2_000_000 },
  { label: "API requests", value: 74_000, max: 100_000 },
];

const invoices = [
  {
    id: "INV-0042",
    date: "2026-11-01",
    detail: "Pro plan, Nov 1 to Nov 30",
    amount: 24,
  },
  {
    id: "INV-0037",
    date: "2026-10-01",
    detail: "Pro plan, Oct 1 to Oct 31",
    amount: 24,
  },
  {
    id: "INV-0031",
    date: "2026-09-01",
    detail: "Pro plan, Sep 1 to Sep 30",
    amount: 24,
  },
  {
    id: "INV-0026",
    date: "2026-08-12",
    detail: "Pro plan, Aug 12 to Aug 31",
    amount: 15.48,
  },
];

const currency = { style: "currency", currency: "USD" } as const;
const money = new Intl.NumberFormat("en-US", currency);
const compact = new Intl.NumberFormat("en-US", {
  notation: "compact",
  maximumFractionDigits: 2,
});
const day = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
  timeZone: "UTC",
});

export function BillingSettings() {
  const [current, setCurrent] = useState("pro");
  const [selected, setSelected] = useState("pro");
  const [confirming, setConfirming] = useState(false);
  const [card, setCard] = useState<PaymentCard>({
    brand: "Visa",
    last4: "4242",
    expiry: "08/28",
  });
  const plan = plans.find((item) => item.id === current) ?? plans[0];
  const next = plans.find((item) => item.id === selected) ?? plans[0];
  const changed = selected !== current;
  const tooSmall = next.seats < seatsUsed;
  const difference = ((next.price - plan.price) * daysLeft) / daysInPeriod;

  return (
    <SettingsShell
      current="billing"
      title="Billing"
      description="Manage the plan, usage, and payment details for Kestrel Insights."
    >
      <div className="grid gap-5">
        <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_minmax(0,20rem)]">
          <Card className="self-start">
            <CardHeader>
              <CardTitle as="h2">Plan</CardTitle>
              <CardDescription>
                {plan.price > 0
                  ? `Your plan renews on Dec 1, 2026 for ${money.format(plan.price)}.`
                  : "Your plan is free."}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <RadioGroup
                aria-label="Plan"
                value={selected}
                onChange={setSelected}
                className="gap-2"
              >
                {plans.map((item) => (
                  <RadioField key={item.id} value={item.id} variant="card">
                    <RadioButton>
                      <RadioIndicator />
                      <RadioLabel className="flex flex-1 flex-wrap items-center gap-2">
                        {item.name}
                        {item.id === current && (
                          <Badge variant="accent">Current</Badge>
                        )}
                      </RadioLabel>
                      <span className="font-semibold tabular-nums">
                        ${item.price}
                        <span
                          aria-hidden="true"
                          className="font-normal text-muted-foreground"
                        >
                          /mo
                        </span>
                        <span className="sr-only"> per month</span>
                      </span>
                    </RadioButton>
                    <RadioDescription>{item.description}</RadioDescription>
                  </RadioField>
                ))}
              </RadioGroup>
            </CardContent>
            <Presence show={changed} collapse>
              <div className="grid gap-4 border-t border-border/70 p-5">
                {tooSmall ? (
                  <Alert
                    variant="warning"
                    title={`${next.name} has ${next.seats} seats`}
                  >
                    Your workspace uses {seatsUsed} seats. Remove{" "}
                    {seatsUsed - next.seats} members before you change to this
                    plan.
                  </Alert>
                ) : (
                  <dl className="grid gap-1.5 text-sm">
                    <div className="flex items-baseline justify-between gap-4">
                      <dt className="text-muted-foreground">
                        {difference >= 0
                          ? `Due today for the ${daysLeft} days left`
                          : "Credit on your next invoice"}
                      </dt>
                      <dd className="font-semibold">
                        <AnimatedNumber
                          value={Math.abs(difference)}
                          formatOptions={currency}
                        />
                      </dd>
                    </div>
                    <div className="flex items-baseline justify-between gap-4">
                      <dt className="text-muted-foreground">
                        Each month from Dec 1
                      </dt>
                      <dd className="font-semibold">
                        <AnimatedNumber
                          value={next.price}
                          formatOptions={currency}
                        />
                      </dd>
                    </div>
                  </dl>
                )}
                <div className="flex flex-wrap justify-end gap-2">
                  <Button
                    size="sm"
                    variant="ghost"
                    onPress={() => setSelected(current)}
                  >
                    Keep {plan.name}
                  </Button>
                  <Button
                    size="sm"
                    isDisabled={tooSmall}
                    onPress={() => setConfirming(true)}
                  >
                    Change to {next.name}
                  </Button>
                </div>
              </div>
            </Presence>
          </Card>
          <div className="grid content-start gap-5">
            <Card>
              <CardHeader>
                <CardTitle as="h2">Usage</CardTitle>
                <CardDescription>Nov 1 to Nov 30, 2026</CardDescription>
              </CardHeader>
              <CardContent className="grid gap-4">
                {usage.map((item) => (
                  <Meter
                    key={item.label}
                    label={item.label}
                    value={item.value}
                    maxValue={item.max}
                    valueLabel={`${compact.format(item.value)} of ${compact.format(item.max)}`}
                    className="**:data-[slot=meter-value]:font-sans"
                  />
                ))}
              </CardContent>
            </Card>
            <Card>
              <CardHeader>
                <CardTitle as="h2">Payment method</CardTitle>
              </CardHeader>
              <CardContent className="flex items-center gap-3">
                <span className="grid size-9 shrink-0 place-items-center rounded-lg bg-muted text-muted-foreground ring-1 ring-border/70">
                  <CreditCardIcon size={18} aria-hidden="true" />
                </span>
                <div className="min-w-0 flex-1 text-sm">
                  <p className="truncate font-medium">
                    {card.brand} ending in {card.last4}
                  </p>
                  <p className="text-xs leading-5 text-muted-foreground">
                    Expires {card.expiry}
                  </p>
                </div>
                <PaymentMethodDialog
                  onSave={(nextCard) => {
                    setCard(nextCard);
                    showToast({
                      title: "Card updated",
                      description: `We charge ${nextCard.brand} ending in ${nextCard.last4} from Dec 1.`,
                      variant: "success",
                    });
                  }}
                />
              </CardContent>
            </Card>
          </div>
        </div>
        <Card className="overflow-hidden">
          <CardHeader className="pb-4">
            <CardTitle as="h2">Invoices</CardTitle>
            <CardDescription>
              We send each invoice to billing@kestrel.app.
            </CardDescription>
          </CardHeader>
          <TableContainer className="rounded-none border-x-0 border-b-0 shadow-none">
            <Table aria-label="Invoices" className="min-w-184 w-full!">
              <TableHeader>
                <Column isRowHeader width={120}>
                  Invoice
                </Column>
                <Column width={130}>Date</Column>
                <Column width={240}>Details</Column>
                <Column width={90}>Status</Column>
                <Column width={100} className="text-end">
                  Amount
                </Column>
                <Column width={64}>
                  <span className="sr-only">Download</span>
                </Column>
              </TableHeader>
              <TableBody items={invoices}>
                {(invoice) => (
                  <Row id={invoice.id}>
                    <Cell className="font-mono text-xs">{invoice.id}</Cell>
                    <Cell className="text-muted-foreground">
                      <time dateTime={invoice.date}>
                        {day.format(new Date(`${invoice.date}T00:00:00Z`))}
                      </time>
                    </Cell>
                    <Cell className="text-muted-foreground">
                      {invoice.detail}
                    </Cell>
                    <Cell>
                      <Badge variant="success">Paid</Badge>
                    </Cell>
                    <Cell className="text-end font-medium tabular-nums">
                      {money.format(invoice.amount)}
                    </Cell>
                    <Cell className="text-end">
                      <Button
                        variant="ghost"
                        size="sm"
                        iconOnly
                        aria-label={`Download ${invoice.id}`}
                        onPress={() =>
                          showToast({
                            title: `${invoice.id}.pdf is downloading`,
                          })
                        }
                      >
                        <DownloadSimpleIcon aria-hidden="true" />
                      </Button>
                    </Cell>
                  </Row>
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </Card>
      </div>
      <ConfirmPlanDialog
        isOpen={confirming}
        onOpenChange={setConfirming}
        from={plan}
        to={next}
        onConfirm={() => {
          setCurrent(next.id);
          showToast({
            title: `Kestrel Insights is on the ${next.name} plan`,
            variant: "success",
          });
        }}
      />
    </SettingsShell>
  );
}

"use client";

import { Button } from "../../vip-ui/button";
import {
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "../../vip-ui/dialog";
import { daysInPeriod, daysLeft, type Plan } from "./billing-settings";

const money = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
});

export function ConfirmPlanDialog({
  isOpen,
  onOpenChange,
  from,
  to,
  onConfirm,
}: {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  from: Plan;
  to: Plan;
  onConfirm: () => void;
}) {
  const upgrade = to.price > from.price;
  const difference = ((to.price - from.price) * daysLeft) / daysInPeriod;

  return (
    <DialogContent
      role="alertdialog"
      size="sm"
      overlayProps={{ isOpen, onOpenChange }}
    >
      <DialogHeader>
        <DialogTitle>Change to {to.name}?</DialogTitle>
        <DialogDescription>
          {upgrade
            ? `We charge ${money.format(difference)} today for the ${daysLeft} days left in this period. From Dec 1, you pay ${money.format(to.price)} each month.`
            : `The change starts today. We add a credit of ${money.format(-difference)} to your next invoice.`}
        </DialogDescription>
      </DialogHeader>
      <DialogFooter>
        <DialogClose variant="outline">Cancel</DialogClose>
        <Button
          onPress={() => {
            onConfirm();
            onOpenChange(false);
          }}
        >
          {upgrade ? `Pay ${money.format(difference)}` : "Change plan"}
        </Button>
      </DialogFooter>
    </DialogContent>
  );
}

"use client";

import { Button } from "../../vip-ui/button";
import {
  Dialog,
  DialogBody,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "../../vip-ui/dialog";
import { Form } from "../../vip-ui/form";
import { TextField } from "../../vip-ui/text-field";

export interface PaymentCard {
  brand: string;
  last4: string;
  expiry: string;
}

const brands = [
  { pattern: /^4/, name: "Visa" },
  { pattern: /^(5[1-5]|2[2-7])/, name: "Mastercard" },
  { pattern: /^3[47]/, name: "American Express" },
];

function digits(value: string) {
  return value.replace(/\D/g, "");
}

function validateNumber(value: string) {
  const number = digits(value);
  if (number.length < 13 || number.length > 19)
    return "Enter the 13 to 19 digits on the front of the card.";
  let sum = 0;
  for (let index = 0; index < number.length; index++) {
    let digit = Number(number[number.length - 1 - index]);
    if (index % 2 === 1) {
      digit *= 2;
      if (digit > 9) digit -= 9;
    }
    sum += digit;
  }
  return sum % 10 === 0 ? null : "This card number is not correct.";
}

function validateExpiry(value: string) {
  const match = value.trim().match(/^(\d{2})\s*\/\s*(\d{2})$/);
  if (!match) return "Use the format MM/YY.";
  const month = Number(match[1]);
  const year = 2000 + Number(match[2]);
  if (month < 1 || month > 12) return "Enter a month from 01 to 12.";
  if (year < 2026 || (year === 2026 && month < 11))
    return "This card has expired.";
  return null;
}

export function PaymentMethodDialog({
  onSave,
}: {
  onSave: (card: PaymentCard) => void;
}) {
  return (
    <Dialog>
      <Button variant="outline" size="sm">
        Update
      </Button>
      <DialogContent size="sm">
        {({ close }) => (
          <>
            <DialogHeader>
              <DialogTitle>Update card</DialogTitle>
              <DialogDescription>
                We charge this card for your plan from the next invoice.
              </DialogDescription>
              <DialogClose />
            </DialogHeader>
            <Form
              className="contents"
              onSubmit={(event) => {
                event.preventDefault();
                const data = new FormData(event.currentTarget);
                const number = digits(String(data.get("number")));
                onSave({
                  brand:
                    brands.find((brand) => brand.pattern.test(number))?.name ??
                    "Card",
                  last4: number.slice(-4),
                  expiry: String(data.get("expiry")).replace(/\s/g, ""),
                });
                close();
              }}
            >
              <DialogBody className="grid content-start gap-4">
                <TextField
                  name="name"
                  label="Name on card"
                  autoComplete="cc-name"
                  defaultValue="Nadia Okafor"
                  isRequired
                />
                <TextField
                  name="number"
                  label="Card number"
                  autoComplete="cc-number"
                  inputMode="numeric"
                  placeholder="1234 1234 1234 1234"
                  validate={validateNumber}
                  isRequired
                  autoFocus
                />
                <div className="grid grid-cols-2 gap-4">
                  <TextField
                    name="expiry"
                    label="Expiry date"
                    autoComplete="cc-exp"
                    inputMode="numeric"
                    placeholder="MM/YY"
                    validate={validateExpiry}
                    isRequired
                  />
                  <TextField
                    name="cvc"
                    label="Security code"
                    autoComplete="cc-csc"
                    inputMode="numeric"
                    placeholder="CVC"
                    validate={(value) =>
                      /^\d{3,4}$/.test(value) ? null : "Enter 3 or 4 digits."
                    }
                    isRequired
                  />
                </div>
              </DialogBody>
              <DialogFooter>
                <DialogClose variant="outline">Cancel</DialogClose>
                <Button type="submit">Save card</Button>
              </DialogFooter>
            </Form>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
}

"use client";

import {
  BellIcon,
  CreditCardIcon,
  type Icon,
  KeyIcon,
  PaletteIcon,
  PlugsConnectedIcon,
  ShieldCheckIcon,
  UserCircleIcon,
} from "@phosphor-icons/react";
import { type ReactNode, useEffect, useRef } from "react";
import { Avatar } from "../../vip-ui/avatar";
import { Badge } from "../../vip-ui/badge";
import { ScrollFade } from "../../vip-ui/scroll-fade";
import { cn } from "../../vip-ui/utils";

export type SettingsSection =
  | "profile"
  | "notifications"
  | "security"
  | "appearance"
  | "billing"
  | "api-keys"
  | "integrations";

interface SettingsItem {
  id: SettingsSection;
  label: string;
  href: string;
  icon: Icon;
}

const groups: { title: string; items: SettingsItem[] }[] = [
  {
    title: "Account",
    items: [
      {
        id: "profile",
        label: "Profile",
        href: "/blocks/settings-01",
        icon: UserCircleIcon,
      },
      {
        id: "notifications",
        label: "Notifications",
        href: "/blocks/settings-02",
        icon: BellIcon,
      },
      {
        id: "security",
        label: "Security",
        href: "/blocks/security-01",
        icon: ShieldCheckIcon,
      },
      {
        id: "appearance",
        label: "Appearance",
        href: "/blocks/appearance-01",
        icon: PaletteIcon,
      },
    ],
  },
  {
    title: "Workspace",
    items: [
      {
        id: "billing",
        label: "Billing",
        href: "/blocks/billing-01",
        icon: CreditCardIcon,
      },
      {
        id: "api-keys",
        label: "API keys",
        href: "/blocks/api-keys-01",
        icon: KeyIcon,
      },
      {
        id: "integrations",
        label: "Integrations",
        href: "/blocks/integrations-01",
        icon: PlugsConnectedIcon,
      },
    ],
  },
];

const items = groups.flatMap((group) => group.items);

interface SettingsShellProps {
  current: SettingsSection;
  title: string;
  description: string;
  actions?: ReactNode;
  children: ReactNode;
}

export function SettingsShell({
  current,
  title,
  description,
  actions,
  children,
}: SettingsShellProps) {
  const scroller = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const node = scroller.current;
    const active = node?.querySelector<HTMLElement>("[aria-current=page]");
    if (!node || !active) return;
    node.scrollLeft =
      active.offsetLeft - (node.clientWidth - active.offsetWidth) / 2;
  }, []);

  return (
    <div className="min-h-svh bg-muted/30">
      <header className="sticky top-0 z-30 border-b border-border/70 bg-background/85 backdrop-blur-md">
        <div className="mx-auto flex h-16 w-full max-w-7xl items-center gap-3 px-5 sm:px-6 lg:px-8">
          <span
            aria-hidden="true"
            className="grid size-9 shrink-0 place-items-center rounded-xl bg-primary text-base font-bold text-primary-foreground shadow-(--shadow-card)"
          >
            K
          </span>
          <div className="min-w-0">
            <p className="truncate text-sm font-semibold">Kestrel</p>
            <p className="truncate text-xs text-muted-foreground">Settings</p>
          </div>
          <div className="ms-auto flex min-w-0 items-center gap-3">
            <Badge variant="outline" className="max-sm:hidden">
              Pro plan
            </Badge>
            <div className="hidden min-w-0 text-end sm:block">
              <p className="truncate text-sm font-medium leading-5">
                Nadia Okafor
              </p>
              <p className="truncate text-xs leading-4 text-muted-foreground">
                Workspace admin
              </p>
            </div>
            <Avatar name="Nadia Okafor" size="sm" />
          </div>
        </div>
      </header>
      <div className="mx-auto grid w-full max-w-7xl gap-6 px-5 py-5 sm:px-6 md:py-8 lg:grid-cols-[14rem_minmax(0,1fr)] lg:items-start lg:gap-10 lg:px-8">
        <aside className="min-w-0 lg:sticky lg:top-22">
          <nav aria-label="Settings">
            <ScrollFade
              ref={scroller}
              orientation="horizontal"
              className="-mx-5 px-5 scrollbar-none sm:-mx-6 sm:px-6 lg:hidden"
            >
              <ul className="flex w-max gap-1.5 py-1">
                {items.map((item) => (
                  <li key={item.id}>
                    <SettingsLink
                      item={item}
                      active={item.id === current}
                      pill
                    />
                  </li>
                ))}
              </ul>
            </ScrollFade>
            <div className="hidden lg:grid lg:gap-6">
              {groups.map((group) => (
                <div key={group.title} className="min-w-0">
                  <p className="px-3 pb-1.5 text-xs font-medium text-muted-foreground">
                    {group.title}
                  </p>
                  <ul className="grid gap-0.5">
                    {group.items.map((item) => (
                      <li key={item.id}>
                        <SettingsLink
                          item={item}
                          active={item.id === current}
                        />
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </div>
          </nav>
          <div className="mt-7 hidden rounded-xl bg-card p-3.5 shadow-(--shadow-card) ring-1 ring-border/70 lg:block">
            <p className="text-xs font-medium text-muted-foreground">
              Workspace
            </p>
            <p className="mt-2 truncate text-sm font-semibold">
              Kestrel Insights
            </p>
            <p className="truncate text-xs text-muted-foreground">
              12 members · 3 environments
            </p>
          </div>
        </aside>
        <main className="min-w-0">
          <div className="mb-6 flex flex-wrap items-end justify-between gap-x-4 gap-y-3">
            <div className="min-w-0">
              <h1 className="text-2xl font-semibold tracking-[-0.04em]">
                {title}
              </h1>
              <p className="mt-1 max-w-2xl text-sm leading-6 text-muted-foreground">
                {description}
              </p>
            </div>
            {actions}
          </div>
          {children}
        </main>
      </div>
    </div>
  );
}

function SettingsLink({
  item,
  active,
  pill = false,
}: {
  item: SettingsItem;
  active: boolean;
  pill?: boolean;
}) {
  return (
    <a
      href={item.href}
      aria-current={active ? "page" : undefined}
      className={cn(
        "flex min-w-0 items-center gap-2.5 rounded-lg px-3 text-sm font-medium outline-offset-2 outline-transparent transition-[color,background-color] duration-150 ease-out-quint focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-ring",
        pill
          ? "min-h-9 whitespace-nowrap pointer-coarse:min-h-11"
          : "min-h-9 w-full",
        active
          ? "bg-accent text-accent-foreground"
          : "text-muted-foreground hover:bg-muted/70 hover:text-foreground",
      )}
    >
      <item.icon
        size={17}
        weight={active ? "fill" : "regular"}
        aria-hidden="true"
      />
      <span className="truncate">{item.label}</span>
    </a>
  );
}
